import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_ct3d_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cute_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride,
                                            int padding,
                                            int output_padding,
                                            int dilation,
                                            int groups);
