_ct3d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>

#include <cute/tensor.hpp>

using namespace cute;

// Supported fast path: groups=1, stride=1, dilation=1, output_padding=0, K=3.
// For ConvTranspose3d with stride=1/dilation=1:
//   y[n,o,od,oh,ow] = bias[o] + sum_i sum_{rd,rh,rw}
//       x[n,i,od+padding-rd, oh+padding-rh, ow+padding-rw] * w[i,o,rd,rh,rw]
// with out-of-range x treated as zero.

template <typename T>
__global__ void __launch_bounds__(256, 4) conv_transpose3d_s1_k3_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Do, int Ho, int Wo,
    int padding,
    int tiles_d, int tiles_h, int tiles_w)
{
  constexpr int K = 3;
  constexpr int KR = K * K * K;      // 27
  constexpr int TD = 8;
  constexpr int TH = 8;
  constexpr int TW = 8;
  constexpr int HD = TD + K - 1;     // 10
  constexpr int HH = TH + K - 1;     // 10
  constexpr int HW = TW + K - 1;     // 10
  // Halve the input-channel chunk (4 -> 2) so the double-buffered dynamic
  // shared memory drops from 45,312 B to 22,656 B per block. The profiler
  // shows occupancy (33.3%) is limited by the shared-memory requirement;
  // at ~100 KB smem/SM this allows 4 resident blocks (66.7% occupancy),
  // and __launch_bounds__(256, 4) caps registers at 64/thread to match.
  constexpr int IC_CHUNK = 2;
  constexpr int OC_BLOCK = 8;
  constexpr int OC_PER_THREAD = 2;
  constexpr int THREADS = 256;
  constexpr int SP_TILE = TD * TH * TW;       // 512
  constexpr int LANES = 64;                   // one (dy,dx) column per lane
  constexpr int OC_GROUPS = THREADS / LANES;  // 4
  constexpr int J = SP_TILE / LANES;          // 8
  static_assert(OC_GROUPS * OC_PER_THREAD == OC_BLOCK, "OC mapping mismatch");

  const int tid = threadIdx.x;
  const int n = blockIdx.z;
  const int oc0 = blockIdx.y * OC_BLOCK;

  const int t = blockIdx.x;
  const int tw = t % tiles_w;
  const int rem0 = t / tiles_w;
  const int th = rem0 % tiles_h;
  const int td = rem0 / tiles_h;

  const int od0 = td * TD;
  const int oh0 = th * TH;
  const int ow0 = tw * TW;

  const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
  const int64_t sXc = (int64_t)Din * Hin * Win;
  const int64_t sXd = (int64_t)Hin * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Do * Ho * Wo;
  const int64_t sYc = (int64_t)Do * Ho * Wo;
  const int64_t sYd = (int64_t)Ho * Wo;
  const int64_t sYh = (int64_t)Wo;

  const int64_t sWi = (int64_t)Cout * KR;
  const int64_t sWo = (int64_t)KR;
  const int64_t sWd = (int64_t)K * K;
  const int64_t sWh = (int64_t)K;

  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, Cin, Din, Hin, Win),
      make_stride(sXn, sXc, sXd, sXh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, Cout, Do, Ho, Wo),
      make_stride(sYn, sYc, sYd, sYh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, Int<K>{}, Int<K>{}, Int<K>{}),
      make_stride(sWi, sWo, sWd, sWh, Int<1>{})
  );

  Tensor mB = make_tensor(
      make_gmem_ptr(B),
      make_shape(Cout),
      make_stride(Int<1>{})
  );

  // The input halo is staged transposed (z innermost) with each (ic,y,x)
  // depth row padded from 10 to 12 floats so every row is 16B aligned.
  // The compute loop then fetches each 10-deep window with vectorized
  // float4/float2 shared-memory loads instead of 10 scalar LDS, cutting
  // LDS issue pressure in the FMA-heavy inner loop.
  extern __shared__ char smem_raw[];
  constexpr int HDP = HD + 2;                            // 12
  constexpr int SX_ELEMS = IC_CHUNK * HH * HW * HDP;     // 4*10*10*12 = 4800
  constexpr int SW_ELEMS = OC_BLOCK * IC_CHUNK * KR;     // 8*4*27     = 864
  T* const sX_ptr[2] = { reinterpret_cast<T*>(smem_raw),
                         reinterpret_cast<T*>(smem_raw) + SX_ELEMS };
  constexpr int SX_ELEMS = IC_CHUNK * HH * HW * HDP;     // 2*10*10*12 = 2400
  constexpr int SW_ELEMS = OC_BLOCK * IC_CHUNK * KR;     // 8*2*27     = 432
                         sX_ptr[1] + SX_ELEMS + SW_ELEMS };
  auto sW_layout = make_layout(
      make_shape(Int<OC_BLOCK>{}, Int<IC_CHUNK>{}, Int<KR>{}),
      make_stride(Int<IC_CHUNK * KR>{}, Int<KR>{}, Int<1>{})
  );

  const int lane = tid & (LANES - 1);  // 0..63 spatial (dy,dx) lanes
  const int oc = tid / LANES;          // 0..3 output-channel group
  const int ocl0 = oc * OC_PER_THREAD;
  const int ocl1 = ocl0 + 1;
  const int ocg0 = oc0 + ocl0;
  const int ocg1 = oc0 + ocl1;
  const bool oc_valid0 = (ocg0 < Cout);
  const bool oc_valid1 = (ocg1 < Cout);
  // Keep the J-depth register blocking, and additionally register-block two
  // adjacent output channels per thread. The staged 10-deep x window is now
  // consumed by two accumulators instead of being re-read from shared memory
  // by a second thread with a different output channel.
  const int dy = lane >> 3;
  const int dx = lane & 7;
  const int gh = oh0 + dy;
  const int gw = ow0 + dx;
  const bool spatial_valid = (gh < Ho) && (gw < Wo);
  const float bval0 = (B != nullptr && oc_valid0) ? (float)mB(ocg0) : 0.0f;
  const float bval1 = (B != nullptr && oc_valid1) ? (float)mB(ocg1) : 0.0f;
  float acc0[J];
  float acc1[J];
  #pragma unroll
  for (int j = 0; j < J; ++j) {
    acc0[j] = bval0;
    acc1[j] = bval1;
  }

  // Halo origins in input coordinates. Out-of-range halo values are zero-filled.
  const int hd0 = od0 + padding - (K - 1);
  const int hh0 = oh0 + padding - (K - 1);
  const int hw0 = ow0 + padding - (K - 1);

  // Software-pipelined double buffering: stage the next input-channel chunk's
  // halo/weights into the alternate shared-memory buffer while computing on the
  // current one, hiding global-load latency behind the FMA-heavy compute.
  auto load_stage = [&](int ic0, int st) {
    T* sXp = sX_ptr[st];
    T* sWp = sW_ptr[st];
    // Load the IC_CHUNK x 10 x 10 x 10 input halo for this output tile,
    // storing it z-innermost so compute can use vectorized smem loads.
    for (int idx = tid; idx < IC_CHUNK * HH * HW * HD; idx += THREADS) {
      const int pos = idx % (HH * HW * HD);
      const int icc = idx / (HH * HW * HD);
      const int iy = pos / (HW * HD);
      const int rem = pos - iy * (HW * HD);
      const int ix = rem / HD;
      const int iz = rem - ix * HD;
      const int ic = ic0 + icc;
      const int xd = hd0 + iz;
      const int xh = hh0 + iy;
      const int xw = hw0 + ix;
      T v = T(0);
      if (ic < Cin &&
          (unsigned)xd < (unsigned)Din &&
          (unsigned)xh < (unsigned)Hin &&
          (unsigned)xw < (unsigned)Win) {
        v = mX(n, ic, xd, xh, xw);
      }
      sXp[((icc * HH + iy) * HW + ix) * HDP + iz] = v;
    }
    // Load OC_BLOCK x IC_CHUNK x 27 weights.
    for (int idx = tid; idx < OC_BLOCK * IC_CHUNK * KR; idx += THREADS) {
      const int r = idx % KR;
      const int tmp = idx / KR;
      const int icc = tmp % IC_CHUNK;
      const int occ = tmp / IC_CHUNK;
      const int rd = r / 9;
      const int rem = r - rd * 9;
      const int rh = rem / 3;
      const int rw = rem - rh * 3;
      const int ic = ic0 + icc;
      const int oc_g = oc0 + occ;
      T v = T(0);
      if (ic < Cin && oc_g < Cout) {
        v = mW(ic, oc_g, rd, rh, rw);
      }
      sWp[idx] = v;
    }
  };
  int stage = 0;
  load_stage(0, stage);
  __syncthreads();
  for (int ic0 = 0; ic0 < Cin; ic0 += IC_CHUNK) {
    const int next_ic0 = ic0 + IC_CHUNK;
    if (next_ic0 < Cin) {
      load_stage(next_ic0, stage ^ 1);
    }
    Tensor sW = make_tensor(make_smem_ptr(sW_ptr[stage]), sW_layout);
    const float* sXf = reinterpret_cast<const float*>(sX_ptr[stage]);
    // Register-block the eight depth outputs. Each thread's J outputs share the
    // same y/x position and overlap along z, so stage the 10-deep input window
    // once and reuse every weight across all eight accumulators.
    if (oc_valid0 || oc_valid1) {
      #pragma unroll
      for (int icc = 0; icc < IC_CHUNK; ++icc) {
        #pragma unroll
        for (int rh = 0; rh < K; ++rh) {
          const int iy = dy + (K - 1) - rh;
          #pragma unroll
          for (int rw = 0; rw < K; ++rw) {
            const int ix = dx + (K - 1) - rw;
            const float* xrow = sXf + ((icc * HH + iy) * HW + ix) * HDP;
            const float4 za = *reinterpret_cast<const float4*>(xrow);
            const float4 zb = *reinterpret_cast<const float4*>(xrow + 4);
            const float2 zc = *reinterpret_cast<const float2*>(xrow + 8);
            float xv[HD];
            xv[0] = za.x; xv[1] = za.y; xv[2] = za.z; xv[3] = za.w;
            xv[4] = zb.x; xv[5] = zb.y; xv[6] = zb.z; xv[7] = zb.w;
            xv[8] = zc.x; xv[9] = zc.y;
            #pragma unroll
              for (int rd = 0; rd < K; ++rd) {
                const int r = rd * 9 + rh * 3 + rw;
                const float wv0 = (float)sW(ocl0, icc, r);
                const float wv1 = (float)sW(ocl1, icc, r);
                #pragma unroll
                for (int j = 0; j < J; ++j) {
                  const float xv_j = xv[j + (K - 1) - rd];
                  acc0[j] += xv_j * wv0;
                  acc1[j] += xv_j * wv1;
