          }
        }
      }
    }
    __syncthreads();
    stage ^= 1;
  }

  #pragma unroll
  for (int j = 0; j < J; ++j) {
    const int gd = od0 + j;
    if (!spatial_valid || gd >= Do) continue;
    if (oc_valid0) mY(n, ocg0, gd, gh, gw) = static_cast<T>(acc0[j]);
    if (oc_valid1) mY(n, ocg1, gd, gh, gw) = static_cast<T>(acc1[j]);
  }
}

