def _triple(v):
    if isinstance(v, tuple):
        return tuple(int(x) for x in v)
    return (int(v), int(v), int(v))


class ModelNew(nn.Module):
    """
    ConvTranspose3d implemented with one custom CUTE/CUDA kernel in forward().

    The custom kernel is specialized for the provided workload configuration:
    groups=1, stride=1, dilation=1, output_padding=0, kernel_size=3, float32 CUDA tensors.
    Parameters are still created through nn.ConvTranspose3d so initialization/state_dict
    semantics match the reference module.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = _triple(kernel_size)
        self.stride = _triple(stride)
        self.padding = _triple(padding)
        self.output_padding = _triple(output_padding)
        self.dilation = _triple(dilation)
        self.groups = int(groups)
        self.use_bias = bool(bias)

        self.conv_transpose3d = nn.ConvTranspose3d(
            self.in_channels,
            self.out_channels,
            self.kernel_size,
            stride=self.stride,
            padding=self.padding,
            output_padding=self.output_padding,
            dilation=self.dilation,
            groups=self.groups,
            bias=self.use_bias,
        )
        self._ext = _ct3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        s = self.stride
        p = self.padding
        op = self.output_padding
        d = self.dilation
        return self._ext.conv_transpose3d_cute_forward(
            x,
            self.conv_transpose3d.weight,
            self.conv_transpose3d.bias if self.conv_transpose3d.bias is not None else None,
            int(s[0]),
            int(p[0]),
            int(op[0]),
            int(d[0]),
            int(self.groups),
        )

